#!/bin/sh
# SPDX-License-Identifier: GPL-3.0-or-later

name=$1

shift

cat <<EOF
/* Generated by $0 */

#ifndef ${name}_H
#define ${name}_H

EOF

while read file; do
	printf '#define '

	printf '%s ' $file | sed $* -e s,/,_,g | tr [:lower:] [:upper:]

	if [ -s $file ]; then
		sed 's/^.*$/"&"/' $file
	else
		printf '""\n'
	fi
done

cat <<EOF

#endif /* ${name}_H */
EOF
